//! Offline MITRE ATT&CK technique names for the ids rules cite. The table is
//! generated by `scripts/generate-mitre-attack.py` from the ATT&CK Enterprise
//! STIX bundle; its terms are in THIRD-PARTY-NOTICES.md.
use std::sync::OnceLock;

const TABLE: &str = include_str!("../assets/mitre_attack_enterprise.tsv");

/// One row of the table: id, name, tactic short names (comma separated).
type Entry = (&'static str, &'static str, &'static str);

fn entries() -> &'static [Entry] {
    static ENTRIES: OnceLock<Vec<Entry>> = OnceLock::new();
    ENTRIES.get_or_init(|| {
        let mut rows: Vec<Entry> = TABLE
            .lines()
            .filter(|line| !line.starts_with('#'))
            .filter_map(|line| {
                let mut parts = line.splitn(3, '\t');
                Some((parts.next()?, parts.next()?, parts.next().unwrap_or("")))
            })
            .collect();
        rows.sort_unstable();
        rows
    })
}

fn entry(id: &str) -> Option<&'static Entry> {
    let rows = entries();
    rows.binary_search_by(|(key, ..)| (*key).cmp(id))
        .ok()
        .map(|index| &rows[index])
}

fn name(id: &str) -> Option<&'static str> {
    entry(id).map(|row| row.1)
}

/// An ATT&CK tactic (v20: Stealth and Defense Impairment replace Defense
/// Evasion), in kill-chain order.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum Tactic {
    Reconnaissance,
    ResourceDevelopment,
    InitialAccess,
    Execution,
    Persistence,
    PrivilegeEscalation,
    Stealth,
    DefenseImpairment,
    CredentialAccess,
    Discovery,
    LateralMovement,
    Collection,
    CommandAndControl,
    Exfiltration,
    Impact,
}

impl Tactic {
    /// Every tactic, in kill-chain order.
    pub const ALL: [Tactic; 15] = [
        Self::Reconnaissance,
        Self::ResourceDevelopment,
        Self::InitialAccess,
        Self::Execution,
        Self::Persistence,
        Self::PrivilegeEscalation,
        Self::Stealth,
        Self::DefenseImpairment,
        Self::CredentialAccess,
        Self::Discovery,
        Self::LateralMovement,
        Self::Collection,
        Self::CommandAndControl,
        Self::Exfiltration,
        Self::Impact,
    ];

    /// The name ATT&CK shows.
    pub fn name(self) -> &'static str {
        match self {
            Self::Reconnaissance => "Reconnaissance",
            Self::ResourceDevelopment => "Resource Development",
            Self::InitialAccess => "Initial Access",
            Self::Execution => "Execution",
            Self::Persistence => "Persistence",
            Self::PrivilegeEscalation => "Privilege Escalation",
            Self::Stealth => "Stealth",
            Self::DefenseImpairment => "Defense Impairment",
            Self::CredentialAccess => "Credential Access",
            Self::Discovery => "Discovery",
            Self::LateralMovement => "Lateral Movement",
            Self::Collection => "Collection",
            Self::CommandAndControl => "Command and Control",
            Self::Exfiltration => "Exfiltration",
            Self::Impact => "Impact",
        }
    }

    /// The kill-chain phase short name the bundled table uses.
    fn slug(self) -> &'static str {
        match self {
            Self::Reconnaissance => "reconnaissance",
            Self::ResourceDevelopment => "resource-development",
            Self::InitialAccess => "initial-access",
            Self::Execution => "execution",
            Self::Persistence => "persistence",
            Self::PrivilegeEscalation => "privilege-escalation",
            Self::Stealth => "stealth",
            Self::DefenseImpairment => "defense-impairment",
            Self::CredentialAccess => "credential-access",
            Self::Discovery => "discovery",
            Self::LateralMovement => "lateral-movement",
            Self::Collection => "collection",
            Self::CommandAndControl => "command-and-control",
            Self::Exfiltration => "exfiltration",
            Self::Impact => "impact",
        }
    }

    /// The tactic named `label` ("Defense evasion", the older name of Stealth,
    /// included), ignoring case.
    pub fn from_label(label: &str) -> Option<Self> {
        let label = label.trim();
        if label.eq_ignore_ascii_case("defense evasion") {
            return Some(Self::Stealth);
        }
        Self::ALL
            .into_iter()
            .find(|tactic| tactic.name().eq_ignore_ascii_case(label))
    }

    /// The tactic's colour as RGB, for a light or a dark surface. Spaced round
    /// the hue wheel in kill-chain steps of 168 degrees so neighbouring tactics
    /// differ most; every colour is at least 4.2:1 against white (light) and
    /// 6.5:1 against the dark panel (dark), so it holds as a 1 px outline or a
    /// dot. Text on a badge keeps the theme's own colour.
    pub fn rgb(self, light: bool) -> [u8; 3] {
        const DARK: [[u8; 3]; 15] = [
            [251, 129, 122],
            [0, 199, 197],
            [246, 127, 165],
            [0, 200, 154],
            [230, 131, 205],
            [104, 195, 109],
            [204, 141, 238],
            [157, 185, 62],
            [169, 153, 255],
            [198, 170, 15],
            [124, 167, 255],
            [227, 154, 31],
            [61, 181, 255],
            [245, 139, 77],
            [0, 192, 232],
        ];
        const LIGHT: [[u8; 3]; 15] = [
            [179, 55, 54],
            [0, 131, 130],
            [173, 53, 99],
            [0, 132, 88],
            [159, 60, 138],
            [9, 127, 35],
            [136, 71, 169],
            [92, 117, 0],
            [105, 83, 189],
            [132, 102, 0],
            [58, 97, 196],
            [158, 84, 0],
            [0, 112, 187],
            [174, 67, 0],
            [0, 123, 164],
        ];
        let at = self as usize;
        if light { LIGHT[at] } else { DARK[at] }
    }
}

/// The tactics of a technique or sub-technique, in kill-chain order (empty for
/// an id the table does not know). T1055 is Privilege Escalation and Stealth.
pub fn tactics(id: &str) -> Vec<Tactic> {
    let id = id.trim().to_ascii_uppercase();
    let Some((_, _, slugs)) = entry(&id) else {
        return Vec::new();
    };
    let mut found: Vec<Tactic> = slugs
        .split(',')
        .filter_map(|slug| Tactic::ALL.into_iter().find(|tactic| tactic.slug() == slug))
        .collect();
    found.sort();
    found
}

/// The technique's name; a sub-technique reads "Parent: Sub-technique" as
/// ATT&CK writes it. `None` for an id the bundled table does not know.
pub fn technique_name(id: &str) -> Option<String> {
    let id = id.trim().to_ascii_uppercase();
    let sub = name(&id)?;
    match id.split_once('.') {
        Some((parent, _)) => Some(match name(parent) {
            Some(parent) => format!("{parent}: {sub}"),
            None => sub.to_owned(),
        }),
        None => Some(sub.to_owned()),
    }
}

/// Whether a recorded run can show the technique: false for one ATT&CK files
/// only under Reconnaissance and Resource Development, which happen before
/// the program runs (a rule that carries such a tag upstream says nothing a
/// run can confirm). An id the bundled table does not know passes.
pub fn observable(id: &str) -> bool {
    let tactics = tactics(id);
    tactics.is_empty()
        || tactics
            .iter()
            .any(|t| !matches!(t, Tactic::Reconnaissance | Tactic::ResourceDevelopment))
}

/// "T1059 Command and Scripting Interpreter"; the bare id when it is unknown.
pub fn technique_label(id: &str) -> String {
    match technique_name(id) {
        Some(name) => format!("{id} {name}"),
        None => id.to_owned(),
    }
}

/// Techniques whose id or name contains `query` (ignoring case), as
/// `technique_label` reads them, in id order, at most `limit`. An empty query
/// matches nothing.
pub fn search(query: &str, limit: usize) -> Vec<String> {
    let query = query.trim().to_ascii_lowercase();
    if query.is_empty() {
        return Vec::new();
    }
    entries()
        .iter()
        .filter(|(id, ..)| id.starts_with('T'))
        .filter(|(id, ..)| {
            let label = technique_label(id).to_ascii_lowercase();
            id.to_ascii_lowercase().contains(&query) || label.contains(&query)
        })
        .take(limit)
        .map(|(id, ..)| technique_label(id))
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn techniques_and_sub_techniques_have_names_and_unknown_ids_stay_bare() {
        assert_eq!(
            technique_label("T1059"),
            "T1059 Command and Scripting Interpreter"
        );
        assert_eq!(
            technique_label("T1059.004"),
            "T1059.004 Command and Scripting Interpreter: Unix Shell"
        );
        assert_eq!(
            technique_name("t1055.008")
                .as_deref()
                .map(|n| n.starts_with("Process Injection")),
            Some(true)
        );
        assert_eq!(technique_label("T9999"), "T9999");
        assert_eq!(technique_label("DET0508"), "DET0508");
        assert!(entries().len() > 600);
    }

    #[test]
    fn techniques_are_found_by_id_or_name() {
        assert!(
            search("cron", 10)
                .iter()
                .any(|label| label == "T1053.003 Scheduled Task/Job: Cron")
        );
        assert_eq!(
            search("t1059.004", 5)[0],
            "T1059.004 Command and Scripting Interpreter: Unix Shell"
        );
        assert!(search("", 5).is_empty() && search("zzzzzz", 5).is_empty());
        assert_eq!(search("process", 3).len(), 3);
    }
}
